// Помощники адаптивного стартового теста чтения (#976cbc): уровни отрывков из placement_attempts (Supabase REST).
// По заметкам QA save_placement_part хранит items/level/outcome; точное имя поля в строке placement_attempts при записи
// не сверено — поэтому ищем в строке массив объектов с числовым level. Не нашли — понятная ошибка «остановиться и сообщить».
import { Page } from '@playwright/test';
import { fetchPlacementAttempts, trackSupabaseRest } from '../placement-reading/reading.helpers';

type Json = unknown;

/** Все массивы объектов, у каждого элемента которых есть числовой level (с путём в строке). */
function findLevelArrays(value: Json, pathSoFar: string, out: { path: string; levels: number[] }[]) {
  if (Array.isArray(value)) {
    if (value.length > 0 && value.every((v) => v && typeof v === 'object' && typeof (v as Record<string, unknown>).level === 'number')) {
      out.push({ path: pathSoFar, levels: value.map((v) => (v as { level: number }).level) });
    }
    value.forEach((v, i) => findLevelArrays(v, `${pathSoFar}[${i}]`, out));
  } else if (value && typeof value === 'object') {
    for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
      let parsed: Json = v;
      if (typeof v === 'string' && /^[[{]/.test(v.trim())) {
        try {
          parsed = JSON.parse(v);
        } catch {
          /* не JSON */
        }
      }
      findLevelArrays(parsed, pathSoFar ? `${pathSoFar}.${k}` : k, out);
    }
  }
}

/**
 * Уровни отрывков чтения в порядке показа из единственной строки placement_attempts ребёнка.
 * Предпочтение — массиву, путь которого содержит «read» (часть чтения).
 */
export async function placementPassageLevels(
  page: Page,
  tracker: ReturnType<typeof trackSupabaseRest>,
  childId: string,
): Promise<{ levels: number[]; row: Record<string, unknown> }> {
  const rows = await fetchPlacementAttempts(page, tracker, childId);
  if (rows.length !== 1) throw new Error(`placement_attempts: ожидалась 1 строка, получено ${rows.length} — остановиться и сообщить`);
  const found: { path: string; levels: number[] }[] = [];
  findLevelArrays(rows[0], '', found);
  const pick = found.find((f) => /read/i.test(f.path)) ?? found[0];
  if (!pick) {
    throw new Error(
      `В строке placement_attempts нет массива отрывков с полем level — структура отличается от заметок QA, остановиться и сообщить: ${JSON.stringify(rows[0]).slice(0, 800)}`,
    );
  }
  return { levels: pick.levels, row: rows[0] };
}

/** Шаг самооценки по комментарию программиста 01.11: «קל» +2, «בסדר» +1, «קשה» −2, «לא בטוח» −1; диапазон 1–10. */
export const RATING_STEP = { 'קל': 2, 'בסדר': 1, 'קשה': -2, 'לא בטוח/ה': -1 } as const;
export const clampLevel = (n: number) => Math.min(10, Math.max(1, n));
